function isValidPlatoId(value:string){return /^[A-Za-z0-9_-]+$/.test(value.trim());}
function avatarStoragePath(value:string){
 if(!value)return '';
 if(value.startsWith('http://')||value.startsWith('https://')){
  const markers=['/storage/v1/object/public/avatars/','/storage/v1/object/sign/avatars/','/storage/v1/object/authenticated/avatars/'];
  for(const marker of markers){const i=value.indexOf(marker);if(i>=0){try{return decodeURIComponent(value.slice(i+marker.length).split('?')[0]);}catch{return value.slice(i+marker.length).split('?')[0]}}}
  return '';
 }
 return value;
}
async function getPrivateAvatarUrl(value:string,userId:string){
 if(!value||!supabase)return '';
 const path=avatarStoragePath(value);
 if(!path||!path.startsWith(userId+'/'))return '';
 const {data,error}=await supabase.storage.from('avatars').createSignedUrl(path,3600);
 return error||!data?.signedUrl?'':data.signedUrl;
}
